function locale([title, description, headline, labels, body, pros, cons, questions, answers]) {
  return { title, description, headline, labels: labels.split('|'), body, pros: pros.split('|'), cons: cons.split('|'), faq: questions.split('|').map((q, i) => [q, answers[i]]) };
}

